/* DEPTH-1439 · COMPANY Store E&M page (red blocks: intro, machine park, production sequence, records) merged into the FLUXX walk. Originals: _ARCHIVE/DEPTH-1439 store red to walk/. */
(function () {
  const F = window.FW_SETS;
  const add = [["fluxx","P01",{"k":"Production sequence · Engineering and production preparation","v":"Before serial production begins. Freeze the product specification: Approved energy, voltage, power, dimensions, interfaces and operating conditions. Select the cell: Approved model, capacity, terminal design and specifications. Define the electrical architecture: Approved series and parallel arrangement, module structure and protection scheme. Define the mechanical architecture: Cell support, restraint, expansion allowance, enclosure and mounting. Select the BMS: Correct cell count, current rating, sensing, balancing and communication. Define inverter compatibility: Approved inverter models and communication protocols. Define the thermal system: Passive cooling, fans, heaters or other measures where required. Release drawings and bill of materials: Controlled component list and drawing revisions. Validate the assembly process: Approved joining, fastening, insulation and wiring methods. Define production tests: Test sequence, limits, equipment and failure handling. Validate prototypes and pilot units: Evidence that design and process meet the requirements. Release production instructions: Station instructions, trained operators and calibrated tools."}],["fluxx","P02",{"k":"Production sequence · Receive and inspect the cells","v":"Identity, condition and suitability are established before any irreversible assembly. Receive cell pallets: Record shipment, quantities and delivery condition. Inspect shipping damage: Check impact, crushing, moisture and damaged cartons. Place delivery on quality hold: Unapproved cells cannot enter production. Verify incoming documents: Check model, batch and test records. Unpack cells: Manual station or robotic tray unloading. Scan every cell identifier: Barcode or data matrix scanner. Create the traceability record: Link each cell to its batch and incoming inspection. Inspect cell surfaces: Check swelling, dents, leakage, corrosion and insulation damage. Inspect terminals and vents: Check terminal condition and unobstructed safety vents. Check dimensions and weight: Sampling or full inspection according to the control plan. Stabilise measurement conditions: Defined temperature and rest conditions. Measure open-circuit voltage: Record each cell’s voltage. Measure internal resistance: Approved AC or DC method under consistent conditions. Verify capacity data: Incoming capacity testing to the agreed plan. Check self-discharge where specified: Compare measurements after a defined rest period. Separate nonconforming cells: Locked quality hold and documented disposition. Release accepted cells: Inventory status changes to approved."}],["fluxx","P02",{"k":"Machine park · Cell inspection","v":"Incoming inspection station with scanner, cell tester and climate-controlled rest area. Every cell is scanned, linked to its batch and checked for swelling, dents, leakage and terminal damage. Open circuit voltage and internal resistance are measured under stable conditions. Measured voltage and resistance are compared with approved limits. Capacity and self-discharge are checked to the test plan. Rejected cells go to a locked quality hold."}],["fluxx","P03",{"k":"Production sequence · Match cells and prepare the kit","v":"Cells are matched on measured values, with limits set by engineering. Sort cells into approved groups: Automated sorter or controlled manual selection. Match cells for each module: Capacity, resistance, voltage and batch rules. Adjust cell state of charge if required: Controlled charging or discharging equipment. Allocate a module serial number: Manufacturing execution system (MES). Assign cell positions: Record which cell occupies each position. Prepare the component kit: Insulators, pads, plates, busbars, sensors and fasteners. Verify the kit: Scan component codes and revisions. Prepare the assembly fixture: Confirm correct model, tooling and recipe. Authorise the production order: Assembly is blocked if materials or equipment are unapproved."}],["fluxx","P03",{"k":"Machine park · Cell matching","v":"Automated cell sorter linked to the manufacturing execution system. Cells are grouped by capacity, resistance, voltage and batch. Each module gets a serial number and every cell position is recorded. The sorter blocks cells outside the matching window. The kit is scanned before assembly starts."}],["fluxx","P06",{"k":"Production sequence · Build the cell module","v":"For a module-based design; a cell-to-pack design combines some steps with enclosure assembly. Load the module fixture: Robot or assisted manual handling. Fit the base insulation: Presence and position check. Prepare cell surfaces: Approved cleaning method where required. Apply insulating sheets or pads: Automated dispensing or placement station. Pick and place the cells: Robot with suitable gripping and force control. Verify cell orientation: Camera checks polarity and position. Insert intercell materials: Electrical insulation, thermal barriers or spacers as designed. Fit end plates and restraints: Assembly fixture holds the stack. Apply specified restraint or compression: Controlled force or displacement, following cell requirements. Secure the module structure: Fasteners, bands or other approved construction. Record fastening results: Connected torque tools where applicable. Recheck geometry and polarity: Vision inspection and electrical checks. Prepare terminal contact surfaces: Approved cleaning process. Position busbars: Robotic placement or guided fixture. Join busbars to terminals: Validated laser welding or approved bolted connection. Monitor joining quality: Welding process data or fastening records. Inspect the connections: Visual inspection and specified electrical measurements. Conduct scheduled joint validation: Destructive tests on designated samples or coupons. Install sensing connections: Voltage sensing board, harness or flexible circuit. Install temperature sensors: Defined locations and secure thermal contact. Fit terminal insulation covers: Prevent accidental contact and short circuits. Test the completed module: Voltage, sensing, polarity and insulation checks. Release the module: Approved module moves to pack assembly."}],["fluxx","P06",{"k":"Machine park · Module build","v":"Robotic cell stacking cell, compression fixture and laser busbar welding station. Cells are placed with camera-checked polarity, insulated, compressed to the specified force, and aluminium busbars are laser-welded to the prismatic LFP cell terminals. Welding process data is logged per joint. Connections are inspected visually and electrically, and sample joints are tested destructively on a schedule."}],["fluxx","P18",{"k":"Production sequence · Assemble the finished battery","v":"Every major component is connected to the finished product’s serial number. Load the enclosure onto the line: Conveyor fixture, lifting aid or robot. Scan the enclosure: Confirm model, finish and revision. Inspect enclosure quality: Dimensions, coating, sharp edges and cleanliness. Install internal insulation and supports: Presence and position checks. Install the thermal system: Pads, heat spreaders, fans or heaters where specified. Lift the module into the enclosure: Robot or assisted lift using approved lifting points. Secure the module: Controlled fastening sequence. Install the BMS: Insulated supports and specified clearances. Install the power protection components: Fuses, switches, contactors or semiconductor switching. Install precharge components where required: Depends on the chosen architecture. Install the current sensor or shunt: Correct orientation and connections. Install internal power cables and busbars: Controlled routing and fastening. Connect voltage sensing and temperature sensors: Approved connection sequence. Install communication wiring: CAN, RS485 or other selected interfaces. Connect protective earth and bonding: Where required by the design. Fit external connectors and controls: Power connections, switches, indicators and service interfaces. Install the optional inverter: Integrated variant only. Connect inverter DC, AC and communication: Model-specific work instructions. Inspect cable routing: Strain relief, bend radius, abrasion and clearances. Verify all critical fasteners: Recorded torque or approved verification method. Check for loose objects: Tool control, visual inspection and cleanliness check. Perform the pre-power inspection: Polarity, wiring and safe assembly confirmed."}],["fluxx","P18",{"k":"Machine park · Pack assembly","v":"Assembly line with lift assist, connected torque tools and camera checks. Modules, BMS, fuses, contactors, current sensor, wiring and connectors are installed in the enclosure. Every major part is scanned to the battery serial. Critical fasteners are tightened with recorded torque. A pre-power inspection confirms polarity, wiring and that no loose objects remain."}],["fluxx","P19",{"k":"Production sequence · Receive the BMS and optional inverter","v":"Electronics are accepted only after their own checks. Receive BMS assemblies: Scan board revision and serial number. Review incoming test results: Confirm required board testing has passed. Inspect BMS boards and connectors: ESD-controlled workstation. Verify BMS hardware and firmware compatibility: Compare with the approved FLUXX configuration. Test BMS functions to the control plan: Cell simulator or dedicated BMS tester. Receive optional inverter assemblies: For the integrated all-in-one product. Verify inverter identity and test records: Hardware, firmware, ratings and serial number. Inspect inverter interfaces: Cooling surfaces, terminals, connectors and protective earth. Release approved electronics: Incorrect or failed assemblies are held or rejected."}],["fluxx","P19",{"k":"Machine park · BMS acceptance","v":"ESD-protected test bench with cell simulator. The battery management electronics are inspected and their hardware and firmware revision is compared with the approved configuration. Measurement, balancing and protection functions are checked with simulated cell voltages, without stressing real cells."}],["fluxx","P19",{"k":"Production sequence · Load firmware and configure","v":"Configuration is automatic where possible, from a controlled FLUXX software release. Program approved BMS firmware: Correct version and recorded checksum. Load the product configuration: Cell arrangement, capacity, current and temperature limits. Calibrate measurements: Voltage, current and temperature to the test plan. Configure balancing: Approved thresholds and operating conditions. Configure inverter communication: Correct protocol and device identity. Configure integrated inverter settings: Approved product and destination configuration. Provision device credentials if connected: Unique identity and controlled credential handling. Verify software versions and settings: Automatic comparison with the production order. Link configuration to the serial number: Permanent production record."}],["fluxx","P19",{"k":"Machine park · Firmware and configuration","v":"Programming station connected to the released software. Approved BMS firmware and the product configuration are loaded. Voltage, current and temperature measurements are calibrated. Device credentials are created where the battery connects to EMON. Software version and settings are compared automatically with the production order. Saved to EMON: Firmware version, configuration and calibration, linked to the battery serial."}],["fluxx","P21",{"k":"Production sequence · Close, finish and release","v":"Closure keeps access for testing and then verifies the finished enclosure. Complete internal inspection: No damage or changes after testing. Fit seals and gaskets: Correct position, no twisting or contamination. Install the enclosure cover: Controlled fastening. Enclosure sealing checks where specified: Validated test for the enclosure. Inspect external appearance: No dents, scratches, gaps or contamination. Apply the rating label: Correct model, electrical data and required information. Apply serial and QR labels: Readable and linked to the production record. Verify label content by camera: Physical unit, software identity and label match. Set the shipping state of charge: Determined for the product and transport. Activate transport or storage mode: Prevents unintended operation. Protect external terminals: Caps, covers or other approved protection. Approve factory release: Quality authorisation before packaging."}],["fluxx","P22",{"k":"Machine park · Closing and labels","v":"Cover fastening station, label printer and camera verification. Seals and cover are fitted, the rating label and the serial and QR label are applied, and the shipping state of charge is set. The camera checks that label, QR code and software identity match the physical unit. Saved to EMON: Serial number linked to the QR code."}],["fluxx-test","A6",{"k":"Production sequence · Test, cycle and inspect","v":"Tests on every unit, plus separate sample and design qualification tests. Limits come from the approved specification. Controlled first power-up: No unexpected current, fault or abnormal behaviour. Read all cell voltages: Correct channel order and plausible values. Read temperature sensors: Correct number, position mapping and plausible readings. Verify current measurement: Correct polarity and accuracy. Test power switching: Contactors or semiconductor switches operate correctly. Test precharge where fitted: Correct voltage rise and switching sequence. Test communication: Valid data exchange with inverter or simulator. Test protection logic: Approved simulation or controlled test methods. Test indicators and controls: LEDs, buttons, alarms and service functions. Electrical safety tests: Insulation, dielectric and protective bonding tests. Controlled charging: Voltage, current, temperatures and cell spread recorded. Controlled discharging: Performance confirmed against the test plan. Verify capacity or energy: Full measurement where specified, or the validated screening method. Check connection heating: Thermal inspection or sensor data under defined load. Test balancing operation: Intended function confirmed. Test integrated inverter operation: Charge, discharge and AC operating modes. Specified ageing or burn-in: Controlled duration and operating profile. Rest and recheck the unit: Abnormal voltage drift and logged faults checked. Review the complete test record: Automatic pass or fail against approved limits. Divert failed units: Separate rework route with documented investigation and retest."}],["fluxx-test","A6",{"k":"Machine park · End-of-line test","v":"End-of-line tester with charger, load and insulation tester. The battery is powered up, then charged and discharged under control. Cell voltages, temperatures, switching, communication and protection logic are checked. Insulation and safety tests, then a full charge-discharge capacity measurement on every battery. Measured kWh and cell spread are compared with approved limits. Saved to EMON: Measured capacity, cell spread, insulation and protection results, linked to the battery serial."}],["fluxx-test","A7",{"k":"Machine park · Burn-in","v":"Ageing racks with data logging. 24 hours: one full cycle plus 24 hours rest, then voltage drift and self-discharge are checked. Units with abnormal drift or faults are diverted to a separate rework route and fully retested. Saved to EMON: Burn-in result, linked to the battery serial."}],["fluxx-home","02",{"k":"Production sequence · Robotic carton packing","v":"The robot, gripper and carton are engineered around the battery’s mass, centre of gravity and approved handling surfaces. Scan the released battery: The packing line accepts only approved units. Select the packaging recipe: Correct carton and inserts for the model. Erect the carton: Automatic carton erector. Close the carton base: Approved tape, adhesive or fastening. Place the carton on its support fixture: Supports the base during heavy loading. Insert the bottom protective cushion: Robot or automatic insert feeder. Check insert presence: Camera or sensor. Apply surface protection to the battery: Bag, sleeve or protective film where specified. Present the battery at the pickup station: Conveyor stop and position verification. Confirm battery identity and orientation: Scanner and machine vision. Engage the robotic gripper: Mechanical support or another validated gripping system. Verify secure pickup: Grip position, force and load confirmation. Lift the battery from the conveyor: Controlled acceleration and movement. Move the battery above the carton: Collision-checked robot path. Lower the battery into the bottom cushion: Position and force monitoring. Confirm the battery is seated: Height, position or vision check. Release the gripper and withdraw: Controlled movement without catching the carton. Fit side and top protective inserts: Prevent movement and protect surfaces. Add mounting accessories: Bracket, feet or other model-specific items. Add the cable and accessory kit: Separately restrained to avoid damage. Add documents: Installation instructions and shipment information. Verify accessory completeness: Barcode, camera or weight checks. Close the carton: Automatic flap folding. Seal the carton: Taping or approved closure system. Apply product and shipment labels: Model, serial, weight and destination. Apply transport marks and labels: According to the shipment classification. Checkweigh the sealed carton: Compared with the expected weight range. Scan and verify the finished package: Label readability and identity confirmed. Divert incorrect packages: Missing item, wrong weight or unreadable label. Release the carton for palletising: Complete packaging record."}],["fluxx-home","02",{"k":"Machine park · Robotic packing","v":"Packing robot with mechanical support gripper, carton erector and checkweigher. The battery is lifted by its approved structural points, placed in protective inserts with its accessories and sealed in a carton. Accessories are scanned, the carton is weighed and the label is read before release."}],["fluxx-home","02",{"k":"Production sequence · Robotic palletising and dispatch","v":"The link between battery, carton, pallet and shipment is kept. Present an approved pallet: Automatic pallet dispenser or manual loading. Inspect pallet condition: Correct dimensions, strength and condition. Place the bottom sheet if specified: Automatic sheet feeder. Pick up the sealed carton: Palletising robot with suitable gripper. Place the carton in the approved pattern: Orientation and stacking limits respected. Add layer sheets where specified: Protect and stabilise the load. Complete the pallet: Controlled layer count and total weight. Fit edge and top protection: According to the packaging design. Strap the pallet where specified: Controlled strap position and tension. Wrap the pallet: Automatic stretch wrapper. Apply the pallet label: Unique pallet ID and shipment details. Associate carton serials with the pallet: MES or warehouse system. Final dispatch inspection: Load stability, labels and package condition. Verify shipment documents: Product, quantity, destination and transport documents. Move to finished goods storage: Forklift, automated guided vehicle or mobile robot. Load the vehicle or container: Approved handling and load securing. Record dispatch: Shipment date, carrier, pallet IDs and battery serials."}],["fluxx-home","08",{"k":"Machine park · From factory to site","v":"Phone or tablet with the EMON app. The installer scans the QR code on site. EMON finds the battery with its factory results, firmware and settings and adds it to the system without manual entry. EMON checks that the scanned serial, firmware and connected device match. Saved to EMON: The installed battery is linked to its factory record, installer and site."}],["fluxx-trace","01",{"k":"Cell genealogy","v":"Every cell identifier to its module position and finished battery"}],["fluxx-trace","03",{"k":"Assembly record","v":"Stations, dates, operators, equipment and tooling"}],["fluxx-trace","04",{"k":"Connection record","v":"Weld process data or critical fastening results"}],["fluxx-trace","05",{"k":"Component genealogy","v":"BMS, inverter and critical component batches to the battery"}],["fluxx-trace","05",{"k":"Software record","v":"Firmware versions, configuration and provisioning status"}],["fluxx-trace","06",{"k":"Test record","v":"Actual measurements, acceptance limits and pass or fail results"}],["fluxx-trace","06",{"k":"Rework record","v":"Defect, corrective action and retest"}],["fluxx-trace","06",{"k":"Release record","v":"Final quality authorisation"}],["fluxx-trace","07",{"k":"Packaging record","v":"Battery serial, carton, accessories and pallet"}],["fluxx-trace","07",{"k":"Dispatch record","v":"Shipment, carrier and destination"}]];
  add.forEach(([set, code, e]) => { const s = (F[set] && F[set].steps || []).find((x) => x.code === code); if (s) s.extra = (s.extra || []).concat([e]); });
  F['fluxx'].note += ' ' + "This is the production sequence FLUXX is designed around, based on LFP prismatic cells. Exact joining method, test limits, compression and cooling follow the approved product design. Automated stations are shown as a capability once the line is verified.";
  F['fluxx'].intro += ' ' + "Released batteries are packed, checked, palletised and traced through dispatch.";
  F['fluxx-trace'].intro += ' Records kept for every battery make each battery auditable and let a field fault be traced back to its origin. Stages marked Saved to EMON store their results on the server under the battery serial number, so they can be viewed in EMON later.';
})();
